/** הסכמה לעוגיות/אנליטיקה באתר הלקוח — נשמר ב-localStorage */
export const COOKIE_CONSENT_STORAGE_KEY = "mazal_cookie_consent_v1";

export type CookieConsentValue = {
  /** מעקב שימוש (Firebase Analytics) */
  analytics: boolean;
  v: 1;
};

export const COOKIE_CONSENT_EVENT = "mazal:cookie-consent";

export function readCookieConsent(): CookieConsentValue | null {
  if (typeof window === "undefined") return null;
  try {
    const raw = window.localStorage.getItem(COOKIE_CONSENT_STORAGE_KEY);
    if (!raw) return null;
    const o = JSON.parse(raw) as Partial<CookieConsentValue>;
    if (o.v !== 1 || typeof o.analytics !== "boolean") return null;
    return { v: 1, analytics: o.analytics };
  } catch {
    return null;
  }
}

export function writeCookieConsent(value: Omit<CookieConsentValue, "v">): void {
  const full: CookieConsentValue = { v: 1, analytics: value.analytics };
  window.localStorage.setItem(COOKIE_CONSENT_STORAGE_KEY, JSON.stringify(full));
  window.dispatchEvent(new CustomEvent(COOKIE_CONSENT_EVENT, { detail: full }));
}

"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { Cookie, X } from "lucide-react";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import { readCookieConsent, writeCookieConsent } from "@/lib/cookie-consent";

/**
 * באנר תחתון — הסכמה לעוגיות לא חיוניות (אנליטיקה).
 * אחרי בחירה לא מוצג שוב באותו דפדפן. עיצוב תואם צבעי האתר (טרקוטה / קרם).
 */
export function CustomerCookieConsent() {
  const [open, setOpen] = useState(false);

  useEffect(() => {
    setOpen(readCookieConsent() === null);
  }, []);

  const dismiss = (analytics: boolean) => {
    writeCookieConsent({ analytics });
    setOpen(false);
  };

  if (!open) return null;

  return (
    <div
      className={cn(
        "fixed inset-x-0 bottom-0 z-[45] border-t border-border/90 bg-[color-mix(in_srgb,var(--card)_96%,var(--muted))] shadow-[0_-6px_32px_rgba(0,0,0,0.1)] backdrop-blur-md supports-[backdrop-filter]:bg-[color-mix(in_srgb,var(--card)_88%,transparent)]",
      )}
      style={{ paddingBottom: "max(0.75rem, env(safe-area-inset-bottom))" }}
      role="dialog"
      aria-modal="false"
      aria-labelledby="cookie-consent-title"
      aria-describedby="cookie-consent-desc"
    >
      <div className="mx-auto flex w-full max-w-3xl flex-col gap-3 px-3 py-3 sm:flex-row sm:items-center sm:justify-between sm:gap-4 sm:px-4 md:px-5">
        <div className="flex min-w-0 flex-1 gap-2.5 text-right sm:items-start">
          <span
            className="mt-0.5 flex size-9 shrink-0 items-center justify-center rounded-xl bg-primary/10 text-primary"
            aria-hidden
          >
            <Cookie className="size-4.5 stroke-[2]" />
          </span>
          <div className="min-w-0 space-y-1">
            <p
              id="cookie-consent-title"
              className="font-heading text-sm font-semibold text-foreground"
            >
              עוגיות וסטטיסטיקה
            </p>
            <p id="cookie-consent-desc" className="text-xs leading-relaxed text-muted-foreground">
              אנו משתמשים בעוגיות חיוניות לתפעול האתר (סל, התחברות). ניתן לאשר גם שימוש בעוגיות
              לספירת ביקורים ושיפור השירות.{" "}
              <Link
                href="/privacy"
                className="font-medium text-primary underline-offset-2 hover:underline"
              >
                מדיניות פרטיות
              </Link>
            </p>
          </div>
        </div>
        <div className="flex shrink-0 flex-wrap items-center justify-end gap-2 sm:justify-start">
          <Button
            type="button"
            variant="outline"
            size="sm"
            className="h-9 rounded-xl border-border bg-background/80 text-xs font-medium"
            onClick={() => dismiss(false)}
          >
            רק חיוני
          </Button>
          <Button
            type="button"
            size="sm"
            className="h-9 rounded-xl px-4 text-xs font-semibold shadow-sm"
            onClick={() => dismiss(true)}
          >
            אישור והמשך
          </Button>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useEffect } from "react";
import { getFirebaseApp } from "@/lib/firebase/client";
import { isFirebaseConfigured } from "@/lib/firebase/config";
import { COOKIE_CONSENT_EVENT, readCookieConsent } from "@/lib/cookie-consent";

let started = false;

async function initAnalyticsWhenAllowed() {
  if (!isFirebaseConfigured()) return;
  const consent = readCookieConsent();
  if (!consent?.analytics) return;
  if (started) return;
  try {
    const { getAnalytics, isSupported } = await import("firebase/analytics");
    if (!(await isSupported())) return;
    getAnalytics(getFirebaseApp());
    started = true;
  } catch {
    /* ignore */
  }
}

/** Analytics רק אחרי אישור עוגיות באתר הלקוחות (CustomerCookieConsent). */
export function FirebaseAnalytics() {
  useEffect(() => {
    let cancelled = false;
    (async () => {
      await initAnalyticsWhenAllowed();
    })();
    const onConsent = () => {
      if (!cancelled) void initAnalyticsWhenAllowed();
    };
    window.addEventListener(COOKIE_CONSENT_EVENT, onConsent);
    return () => {
      cancelled = true;
      window.removeEventListener(COOKIE_CONSENT_EVENT, onConsent);
    };
  }, []);
  return null;
}

